def apply_coupons(price: Decimal, percents: list[Decimal]) -> Decimal:
    if any((p < 0 or p > 100 for p in percents)):
        raise ValueError('coupon percentages must be between 0 and 100')
    value = price
    for percent in percents[:2]:
